insert into public.profile (id, data) values (1, $json${"firstName":"Alfiz Desta","lastName":"Ariant Permana","title":"Software Engineer","subtitle":"Software Engineer · Backend & Distributed Systems @ UGM","bio":"Software Engineering student at Universitas Gadjah Mada (UGM). Passionate about crafting robust backend architectures, distributed APIs, and developer-native web experiences.","affiliation":"Universitas Gadjah Mada (UGM)","location":"Yogyakarta, ID","availableForWork":true,"statusText":"Available for work / Yogyakarta, ID","email":"alfizdestaap@gmail.com","resumeUrl":"/cv/alfiz-desta-cv.pdf","socialLinks":[{"id":"github","name":"GitHub","url":"https://github.com/exenthiast","handle":"/exenthiast"},{"id":"linkedin","name":"LinkedIn","url":"https://www.linkedin.com/in/alfiz-desta-0a0318326/","handle":"/alfizdesta"},{"id":"instagram","name":"Instagram","url":"https://instagram.com/d.destaz","handle":"/d.destaz"}]}$json$::jsonb)
insert into public.projects (id, data, sort_order, status) values
  ('sim-pondok-tahfidz', $json${"id":"sim-pondok-tahfidz","slug":"sim-pondok-tahfidz","title":"SIM Pondok Tahfidz","category":"Backend Developer","role":"Lead Backend Developer","description":"Sistem Informasi Manajemen Pondok Tahfidz modern untuk tata kelola santri, kurikulum hafalan Al-Qur’an, pencatatan keuangan syariah, dan pelaporan wali santri secara real-time.","techStack":["PHP 8.3","Laravel 13","PostgreSQL","Sanctum","Docker","Vercel"],"liveDemoUrl":"https://simpondokk.vercel.app/","githubUrl":"https://github.com/exenthiast/SIMPondok-Tahfidz-BE","preview":{"src":"/projects/project1.webp","alt":"SIM Pondok Tahfidz interface screenshot","width":1600,"height":1000},"architecture":{"overview":"Modular monolithic architecture with strictly typed service-repository pattern, isolated tenant scopes, and atomic database transactions.","keyDecisions":["PostgreSQL with JSONB fields for extensible tahfidz grade rubric.","Laravel Sanctum token authentication with fine-grained role-based permission gates.","Automated Dockerized container workflow for testing and migration pipelines."]},"keyFeatures":["Pelacakan setoran hafalan harian dan rekap musabaqah santri.","Sistem penagihan iuran syahriah otomatis dengan notifikasi.","Dashboard statistik perkembangan santri untuk asatidz dan wali."]}$json$::jsonb, 0, 'published'),
  ('sia-ugn', $json${"id":"sia-ugn","slug":"sia-ugn","title":"SIA UGN","category":"Backend Developer","role":"Backend Systems Engineer","description":"Sistem Informasi Akademik perguruan tinggi berkapasitas konkurensi tinggi untuk rencana studi mahasiswa, penjadwalan ruang kuliah otomatis, dan transkrip nilai terenkripsi.","techStack":["Node.js","Express","MongoDB","Redis","Docker"],"liveDemoUrl":"https://sia.trisuladana.com","githubUrl":"https://github.com/exenthiast/SIA-UGN-BE","preview":{"src":"/projects/project2.webp","alt":"SIA UGN interface screenshot","width":1600,"height":1000},"architecture":{"overview":"High-throughput RESTful API designed with Redis caching layer and optimistic concurrency locks for KRS traffic surges.","keyDecisions":["Optimistic locking during course selection to prevent race conditions in capacity caps.","In-memory Redis caching for fast syllabus and timetable lookup.","Aggregation pipelines for rapid transcript GPA calculations."]},"keyFeatures":["Pengisian Kartu Rencana Studi (KRS) real-time dengan validasi prasyarat matakuliah.","Algoritma penjadwalan kelas bebas bentrok dosen dan ruangan.","API gateway terisolasi untuk integrasi data kelembagaan."]}$json$::jsonb, 1, 'published'),
  ('bimbel-lazuardy', $json${"id":"bimbel-lazuardy","slug":"bimbel-lazuardy","title":"Bimbel Lazuardy","category":"Frontend Developer","role":"Lead Frontend Developer","description":"Platform pembelajaran interaktif dan bimbingan belajar berbasis web dengan visualisasi progres siswa, tryout ujian berkala, dan modul interaktif.","techStack":["Vue 3","Vite","Pinia","Tailwind CSS","TypeScript"],"liveDemoUrl":"https://lazuardy.trpl.space","githubUrl":"https://github.com/exenthiast/PAD-LAZUARDY-FRONTEND","preview":{"src":"/projects/project3.webp","alt":"Bimbel Lazuardy interface screenshot","width":1600,"height":1000},"architecture":{"overview":"Composition API-driven Single Page Application with centralized Pinia reactive state stores and custom responsive design system tokens.","keyDecisions":["Vue 3 Composition API with script setup for maximum type safety and render performance.","Pinia state hydration for persistent student practice session states.","Zero-dependency SVG chart rendering for progress telemetry."]},"keyFeatures":["Simulasi tryout dengan timer otomatis dan anti-kecurangan tab tracking.","Analisis butir soal dan grafik penguasaan materi per siswa.","Antarmuka ramah mobile untuk akses materi belajar di mana saja."]}$json$::jsonb, 2, 'published')
