  ('exp-kmtedi', $json${"id":"exp-kmtedi","category":"organization","role":"Anggota Divisi Minat dan Bakat","organization":"KMTEDI UGM (Keluarga Mahasiswa Teknologi Rekayasa Perangkat Lunak)","period":"2024 – Sekarang","description":"Mengembangkan program pemberdayaan minat teknologi, kompetisi coding mahasiswa, dan fasilitasi workshop internal Software Engineering di lingkungan Departemen TEDI SV UGM.","division":"Minat dan Bakat","skills":["Community Leadership","Tech Workshop","Event Organization"],"photos":[]}$json$::jsonb, 0, 'published'),
